// Training lineage (spec 003 US1, research R2): the features tma-train reads must come from a
// clean dataset generated by code whose generator paths equal those of the commit at which G0 was
// verified. Closes the gap where data from since-reverted code passes the current-tree G0 guard.
import { canonicalJson } from "@tma/data";
import type { FeatureSource } from "@tma/features";
import type { DatasetHeader, FeatureSet, TrainingConfig } from "@tma/types";

export type LineageReason =
  | "lineage-missing"
  | "lineage-dirty"
  | "lineage-mismatch"
  | "lineage-split-mismatch"
  | "feature-set-mismatch";

/** A training refusal with a named reason (contracts/cli.md; exit 2). */
export class LineageError extends Error {
  constructor(
    readonly reason: LineageReason,
    detail: string,
  ) {
    super(`${reason}: ${detail}`);
    this.name = "LineageError";
  }
}

/** What lineage needs from an open features file. */
export interface LineageFile {
  path: string;
  source: FeatureSource | undefined;
  featureSet: FeatureSet;
}

export interface LineageInputs {
  train: LineageFile;
  val: LineageFile;
  config: TrainingConfig;
  /** Commit of the accepted G0 verdict. */
  g0Commit: string;
  /** True when the generator paths are identical at both commits (git; injected in tests). */
  generatorPathsEqual: (g0Commit: string, dataCommit: string) => boolean;
}

/** Header of a file with complete provenance, or a `lineage-missing` refusal. */
function provenance(f: LineageFile): DatasetHeader & { generator_git_commit: string } {
  const h = f.source?.header;
  if (h === undefined) {
    throw new LineageError(
      "lineage-missing",
      `${f.path} has no source dataset header (features format 1); rebuild it with tma-features from a dataset generated at schema 0.8.0 or later`,
    );
  }
  const commit = h.generator_git_commit;
  if (typeof commit !== "string" || typeof h.generator_git_dirty !== "boolean") {
    throw new LineageError(
      "lineage-missing",
      `${f.path}: source dataset header has no generator provenance (generated before schema 0.8.0); regenerate the dataset`,
    );
  }
  return { ...h, generator_git_commit: commit };
}

/**
 * Refuse training unless both features files trace to one clean dataset whose generator code
 * matches the G0-verified commit, and the feature set matches the config. Returns the train
 * file's source header (recorded in the model manifest).
 */
export function checkLineage(inp: LineageInputs): DatasetHeader {
  const files = [inp.train, inp.val];
  const headers = files.map(provenance);
  const [train, val] = headers;
  if (train === undefined || val === undefined) throw new Error("unreachable");
  files.forEach((f, i) => {
    if (headers[i]?.generator_git_dirty !== false) {
      throw new LineageError(
        "lineage-dirty",
        `${f.path}: source dataset was generated from a dirty tree (--allow-dirty); regenerate it at a clean commit`,
      );
    }
  });
  files.forEach((f, i) => {
    const commit = headers[i]?.generator_git_commit ?? "";
    if (!inp.generatorPathsEqual(inp.g0Commit, commit)) {
      throw new LineageError(
        "lineage-mismatch",
        `${f.path}: generator code at ${commit} differs from the G0-verified commit ${inp.g0Commit} (or that commit is not in history); regenerate at a commit whose generator equals G0's, or re-run G0`,
      );
    }
  });
  const same =
    train.dataset_seed === val.dataset_seed &&
    train.generator_git_commit === val.generator_git_commit &&
    train.generator_version === val.generator_version &&
    canonicalJson(train.parameter_ranges) === canonicalJson(val.parameter_ranges);
  if (!same || train.split !== "train" || val.split !== "validation") {
    throw new LineageError(
      "lineage-split-mismatch",
      `${inp.train.path} (${train.split}, seed ${train.dataset_seed}, commit ${train.generator_git_commit}) and ${inp.val.path} (${val.split}, seed ${val.dataset_seed}, commit ${val.generator_git_commit}) are not the train and validation splits of one dataset`,
    );
  }
  const want = inp.config.feature_set ?? "raw";
  for (const f of files) {
    if (f.featureSet !== want) {
      throw new LineageError(
        "feature-set-mismatch",
        `config ${inp.config.id} expects feature set ${want}; ${f.path} holds ${f.featureSet}`,
      );
    }
  }
  return train;
}
